import { IUserRepository, IProfileRepository, ISessionRepository, IVerificationRepository, IPasswordResetRepository, ILoginHistoryRepository, IAuditRepository } from './auth_interfaces.ts';
import { User, Profile, Session, EmailVerification, PasswordReset, LoginHistory, AuditLog } from '../db/schema.ts';
import { supabase } from '../lib/supabaseClient.ts';
import crypto from 'crypto';
import fs from 'fs';
import path from 'path';

const DB_FILE = path.join(process.cwd(), "db_store.json");

function readLocalUsers(): User[] {
  if (fs.existsSync(DB_FILE)) {
    try {
      const data = JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
      return (data.users || []) as User[];
    } catch (e) {
      console.error('Failed to read local users:', e);
    }
  }
  return [];
}

function writeLocalUsers(users: User[]) {
  if (fs.existsSync(DB_FILE)) {
    try {
      const db = JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
      db.users = users;
      fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));
    } catch (e) {
      console.error('Failed to write local users:', e);
    }
  }
}

export class UserRepository implements IUserRepository {
  async findByEmail(email: string): Promise<User | null> {
    try {
      const { data, error } = await supabase
        .from('User')
        .select('*')
        .eq('email', email)
        .maybeSingle();
      
      if (!error && data) {
        return data as User;
      }
      throw error || new Error('No user data returned from Supabase');
    } catch (e: any) {
      console.warn('Supabase findByEmail failed, attempting local fallback:', e?.message || e);
      const localUsers = readLocalUsers();
      const user = localUsers.find(u => u.email.toLowerCase() === email.toLowerCase());
      return user || null;
    }
  }

  async findById(id: string): Promise<User | null> {
    try {
      const { data, error } = await supabase
        .from('User')
        .select('*')
        .eq('id', id)
        .maybeSingle();
      
      if (!error && data) {
        return data as User;
      }
      throw error || new Error('No user data returned from Supabase');
    } catch (e: any) {
      console.warn('Supabase findById failed, attempting local fallback:', e?.message || e);
      const localUsers = readLocalUsers();
      const user = localUsers.find(u => u.id === id);
      return user || null;
    }
  }

  async create(user: Omit<User, 'id' | 'createdAt' | 'updatedAt'>): Promise<User> {
    const userId = crypto.randomUUID();
    const createdAt = new Date().toISOString();
    const updatedAt = createdAt;
    
    const userToSave: User = {
      id: userId,
      ...user,
      createdAt,
      updatedAt
    };

    try {
      const payload = { ...userToSave } as any;
      delete payload.status; 
      
      const { data, error } = await supabase
        .from('User')
        .insert(payload)
        .select()
        .single();
      
      if (!error && data) {
        return data as User;
      }
      throw error || new Error('Failed to create user in Supabase');
    } catch (e: any) {
      console.error('Supabase user creation threw error, saving locally:', e?.message || e);
      const localUsers = readLocalUsers();
      localUsers.push(userToSave);
      writeLocalUsers(localUsers);
      return userToSave;
    }
  }

  async updateStatus(id: string, status: User['status']): Promise<void> {
    try {
      const { error } = await supabase
        .from('User')
        .update({ status, updatedAt: new Date().toISOString() })
        .eq('id', id);
      if (error) throw error;
    } catch (e: any) {
      console.error('Failed to update status in Supabase, updating locally:', e?.message || e);
      const localUsers = readLocalUsers();
      const user = localUsers.find(u => u.id === id);
      if (user) {
        user.status = status;
        user.updatedAt = new Date().toISOString();
        writeLocalUsers(localUsers);
      }
    }
  }

  async updateLastLogin(id: string): Promise<void> {
    try {
      const { error } = await supabase
        .from('User')
        .update({ updatedAt: new Date().toISOString() })
        .eq('id', id);
      if (error) throw error;
    } catch (e: any) {
      console.error('Failed to update last login in Supabase, updating locally:', e?.message || e);
      const localUsers = readLocalUsers();
      const user = localUsers.find(u => u.id === id);
      if (user) {
        user.updatedAt = new Date().toISOString();
        writeLocalUsers(localUsers);
      }
    }
  }

  async updatePassword(id: string, passwordHash: string): Promise<void> {
    try {
      const { error } = await supabase
        .from('User')
        .update({ password: passwordHash, updatedAt: new Date().toISOString() })
        .eq('id', id);
      if (error) throw error;
    } catch (e: any) {
      console.error('Failed to update password in Supabase, updating locally:', e?.message || e);
      const localUsers = readLocalUsers();
      const user = localUsers.find(u => u.id === id);
      if (user) {
        user.password = passwordHash;
        user.updatedAt = new Date().toISOString();
        writeLocalUsers(localUsers);
      }
    }
  }

  async list(): Promise<User[]> {
    try {
      const { data, error } = await supabase
        .from('User')
        .select('*');
      
      if (!error && data) {
        return data as User[];
      }
      throw error || new Error('Failed to list users from Supabase');
    } catch (e: any) {
      console.warn('Supabase list users failed, returning local list fallback:', e?.message || e);
      return readLocalUsers();
    }
  }

  async update(id: string, updates: Partial<User>): Promise<void> {
    try {
      const payload = { ...updates, updatedAt: new Date().toISOString() };
      const { error } = await supabase
        .from('User')
        .update(payload)
        .eq('id', id);
      if (error) throw error;
    } catch (e: any) {
      console.error('Failed to update user in Supabase, updating locally:', e?.message || e);
      const localUsers = readLocalUsers();
      const userIndex = localUsers.findIndex(u => u.id === id);
      if (userIndex !== -1) {
        localUsers[userIndex] = {
          ...localUsers[userIndex],
          ...updates,
          updatedAt: new Date().toISOString()
        } as User;
        writeLocalUsers(localUsers);
      }
    }
  }

  async delete(id: string): Promise<void> {
    try {
      const { error } = await supabase
        .from('User')
        .delete()
        .eq('id', id);
      if (error) throw error;
    } catch (e: any) {
      console.error('Failed to delete user in Supabase, deleting locally:', e?.message || e);
      const localUsers = readLocalUsers();
      const updated = localUsers.filter(u => u.id !== id);
      writeLocalUsers(updated);
    }
  }
}

export class ProfileRepository implements IProfileRepository {
  async create(profile: Profile): Promise<void> {
    try {
      const payload = { ...profile } as any;
      await supabase
        .from('profiles')
        .upsert(payload, { onConflict: 'user_id' });
    } catch (e: any) {
      console.error('Failed to upsert profile in Supabase:', e?.message || e);
    }
  }

  async getByUserId(userId: string): Promise<Profile | null> {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('user_id', userId)
        .maybeSingle();
      
      if (!error && data) {
        return data as Profile;
      }
    } catch (e: any) {
      console.warn('Supabase getByUserId failed:', e?.message || e);
    }

    return null;
  }

  async update(userId: string, updates: Partial<Profile>): Promise<void> {
    try {
      await supabase
        .from('profiles')
        .update(updates)
        .eq('user_id', userId);
    } catch (e: any) {
      console.error('Failed to update profile in Supabase:', e?.message || e);
    }
  }
}

export class SessionRepository implements ISessionRepository {
  async create(session: Omit<Session, 'id'>): Promise<Session> {
    const id = crypto.randomUUID();
    const record = { id, ...session } as Session;

    try {
      const { data, error } = await supabase
        .from('sessions')
        .insert(record)
        .select()
        .single();
      
      if (!error && data) {
        return data as Session;
      }
    } catch (e: any) {
      console.error('Failed to create session in Supabase:', e?.message || e);
    }
    return record;
  }

  async getByRefreshTokenHash(hash: string): Promise<Session | null> {
    try {
      const { data, error } = await supabase
        .from('sessions')
        .select('*')
        .eq('refresh_token_hash', hash)
        .maybeSingle();
      
      if (!error && data) {
        return data as Session;
      }
    } catch (e: any) {
      console.error('Failed to get session by hash from Supabase:', e?.message || e);
    }
    return null;
  }

  async revoke(id: string): Promise<void> {
    try {
      await supabase
        .from('sessions')
        .update({ revoked_at: new Date().toISOString() })
        .eq('id', id);
    } catch (e: any) {
      console.error('Failed to revoke session in Supabase:', e?.message || e);
    }
  }

  async listByUserId(userId: string): Promise<Session[]> {
    try {
      const { data, error } = await supabase
        .from('sessions')
        .select('*')
        .eq('user_id', userId)
        .is('revoked_at', null);
      
      if (!error && data) {
        return data as Session[];
      }
    } catch (e: any) {
      console.error('Failed to list sessions by user in Supabase:', e?.message || e);
    }
    return [];
  }

  async revokeAllByUserId(userId: string): Promise<void> {
    try {
      await supabase
        .from('sessions')
        .update({ revoked_at: new Date().toISOString() })
        .eq('user_id', userId)
        .is('revoked_at', null);
    } catch (e: any) {
      console.error('Failed to revoke all sessions in Supabase:', e?.message || e);
    }
  }
}

