import { IFollowRepository } from './interfaces.ts';
import { supabase } from '../lib/supabaseClient.ts';
import fs from 'fs';
import path from 'path';

const DB_FILE = path.join(process.cwd(), "db_store.json");

function getLocalFollows(): {followerId: string, followingId: string}[] {
    try {
        if (fs.existsSync(DB_FILE)) {
            const content = fs.readFileSync(DB_FILE, 'utf-8');
            if (content && content.trim()) {
                const db = JSON.parse(content);
                return db.follows || [];
            }
        }
    } catch (e) {
        // ignore
    }
    return [];
}

function saveLocalFollows(follows: {followerId: string, followingId: string}[]): void {
    try {
        if (fs.existsSync(DB_FILE)) {
            const content = fs.readFileSync(DB_FILE, 'utf-8');
            const db = content && content.trim() ? JSON.parse(content) : {};
            db.follows = follows;
            fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));
        } else {
            const db = { follows };
            fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));
        }
    } catch (e) {
        // ignore
    }
}

export class FollowRepository implements IFollowRepository {
    async listFollowers(userId: string): Promise<string[]> {
        try {
            const { data, error } = await supabase
                .from('Follow')
                .select('followerId')
                .eq('followingId', userId);
            if (error) throw error;
            return (data || []).map((f: any) => f.followerId);
        } catch (e: any) {
            const local = getLocalFollows();
            return local.filter(f => f.followingId === userId).map(f => f.followerId);
        }
    }

    async listFollowing(userId: string): Promise<string[]> {
        try {
            const { data, error } = await supabase
                .from('Follow')
                .select('followingId')
                .eq('followerId', userId);
            if (error) throw error;
            return (data || []).map((f: any) => f.followingId);
        } catch (e: any) {
            const local = getLocalFollows();
            return local.filter(f => f.followerId === userId).map(f => f.followingId);
        }
    }

    async list(): Promise<{followerId: string, followingId: string}[]> {
        try {
            const { data, error } = await supabase
                .from('Follow')
                .select('followerId, followingId');
            if (error) throw error;
            return (data || []) as {followerId: string, followingId: string}[];
        } catch (e: any) {
            return getLocalFollows();
        }
    }

    async follow(followerId: string, followingId: string): Promise<void> {
        const local = getLocalFollows();
        if (!local.some(f => f.followerId === followerId && f.followingId === followingId)) {
            local.push({ followerId, followingId });
            saveLocalFollows(local);
        }
        try {
            const { error } = await supabase
                .from('Follow')
                .insert({ followerId, followingId });
            if (error) throw error;
        } catch (e: any) {
            // Supabase table missing or error - handled by local store
        }
    }

    async unfollow(followerId: string, followingId: string): Promise<void> {
        const local = getLocalFollows();
        const filtered = local.filter(f => !(f.followerId === followerId && f.followingId === followingId));
        saveLocalFollows(filtered);
        try {
            const { error } = await supabase
                .from('Follow')
                .delete()
                .eq('followerId', followerId)
                .eq('followingId', followingId);
            if (error) throw error;
        } catch (e: any) {
            // Supabase table missing or error - handled by local store
        }
    }
}

