import { IConnectionRepository } from './interfaces.ts';
import { Connection } from '../types.ts';
import { supabase } from '../lib/supabaseClient.ts';

export class ConnectionRepository implements IConnectionRepository {
  async list(): Promise<Connection[]> {
    try {
      const { data, error } = await supabase
        .from('Connection')
        .select('*');
      
      if (error) throw error;
      return (data || []) as Connection[];
    } catch (e: any) {
      console.warn('Supabase list connections failed:', e?.message || e);
    }
    return [];
  }

  async create(connection: Connection): Promise<void> {
    try {
      const { error } = await supabase
        .from('Connection')
        .insert(connection);
      if (error) throw error;
    } catch (e: any) {
      console.error('Failed to create connection in Supabase:', e?.message || e);
    }
  }

  async delete(requesterId: string, receiverId: string): Promise<void> {
    try {
      const { error } = await supabase
        .from('Connection')
        .delete()
        .match({ requesterId, receiverId });
      if (error) throw error;
    } catch (e: any) {
      console.error('Failed to delete connection in Supabase:', e?.message || e);
    }
  }

  async updateStatus(requesterId: string, receiverId: string, status: 'pending' | 'accepted' | 'declined'): Promise<void> {
    try {
      const { error } = await supabase
        .from('Connection')
        .update({ status })
        .match({ requesterId, receiverId });
      if (error) throw error;
    } catch (e: any) {
      console.error('Failed to update connection status in Supabase:', e?.message || e);
    }
  }
}
