import { IPostRepository } from './interfaces.ts';
import { Post } from '../types.ts';
import { supabase } from '../lib/supabaseClient.ts';
import fs from 'fs';
import path from 'path';

const DB_FILE = path.join(process.cwd(), "db_store.json");

export class PostRepository implements IPostRepository {
    async list(): Promise<Post[]> {
        try {
            const { data, error } = await supabase
                .from('Post')
                .select('*')
                .order('timestamp', { ascending: false });
            if (error) throw error;
            return (data || []) as Post[];
        } catch (e: any) {
            console.error('Failed to list posts from Supabase, attempting local fallback:', e?.message || e);
            if (fs.existsSync(DB_FILE)) {
                try {
                    const data = JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
                    return (data.posts || []) as Post[];
                } catch (e) {
                    console.error('Failed to load local posts:', e);
                }
            }
            return [];
        }
    }

    async create(post: Omit<Post, 'id' | 'timestamp'>): Promise<Post> {
        const timestamp = new Date().toISOString();
        const id = "post_" + Date.now() + "_" + Math.random().toString(36).substr(2, 5);
        const record = { ...post, id, timestamp } as Post;
        try {
            const { data, error } = await supabase
                .from('Post')
                .insert(record)
                .select()
                .single();
            if (error) throw error;
            return data as Post;
        } catch (e) {
            console.warn('Failed to create post in Supabase, saving locally:', e);
            
            if (fs.existsSync(DB_FILE)) {
                try {
                    const db = JSON.parse(fs.readFileSync(DB_FILE, 'utf-8'));
                    if (!db.posts) {
                        db.posts = [];
                    }
                    db.posts.push(record);
                    fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));
                } catch (err) {
                    console.error('Failed to save post locally:', err);
                }
            }

            return record;
        }
    }

    async findById(id: string): Promise<Post | null> {
        try {
            const { data, error } = await supabase
                .from('Post')
                .select('*')
                .eq('id', id)
                .maybeSingle();
            if (error) throw error;
            return data as Post | null;
        } catch (e) {
            console.error('Failed to find post by id in Supabase:', e);
            return null;
        }
    }

    async delete(id: string): Promise<void> {
        try {
            const { error } = await supabase
                .from('Post')
                .delete()
                .eq('id', id);
            if (error) throw error;
        } catch (e) {
            console.error('Failed to delete post in Supabase:', e);
        }
    }

    async update(post: Post): Promise<void> {
        try {
            const { error } = await supabase
                .from('Post')
                .update(post)
                .eq('id', post.id);
            if (error) throw error;
        } catch (e) {
            console.error('Failed to update post in Supabase:', e);
        }
    }

    async filter(predicate: (post: Post) => boolean): Promise<Post[]> {
        const posts = await this.list();
        return posts.filter(predicate);
    }
}
