import { IMessageRepository } from './interfaces.ts';
import { Message } from '../types.ts';
import { supabase } from '../lib/supabaseClient.ts';

export class MessageRepository implements IMessageRepository {
    async list(): Promise<Message[]> {
        try {
            const { data, error } = await supabase
                .from('Message')
                .select('*')
                .order('timestamp', { ascending: false });
            if (error) throw error;
            return (data || []) as Message[];
        } catch (e) {
            console.error('Failed to list messages from Supabase:', e);
            return [];
        }
    }

    async listAllForUser(userId: string): Promise<Message[]> {
        try {
            const { data, error } = await supabase
                .from('Message')
                .select('*')
                .or(`senderId.eq.${userId},receiverId.eq.${userId}`);
            if (error) throw error;
            return (data || []) as Message[];
        } catch (e: any) {
            console.error('Failed to list messages for user from Supabase:', e?.message || e);
            return [];
        }
    }

    async listHistory(userId: string, partnerId: string): Promise<Message[]> {
        const isGroup = partnerId.startsWith("group_");
        try {
            if (isGroup) {
                const { data, error } = await supabase
                    .from('Message')
                    .select('*')
                    .eq('receiverId', partnerId);
                if (error) throw error;
                return (data || []) as Message[];
            } else {
                const { data, error } = await supabase
                    .from('Message')
                    .select('*')
                    .or(`and(senderId.eq.${userId},receiverId.eq.${partnerId}),and(senderId.eq.${partnerId},receiverId.eq.${userId})`);
                if (error) throw error;
                return (data || []) as Message[];
            }
        } catch (e) {
            console.error('Failed to list chat history from Supabase:', e);
            return [];
        }
    }

    async findById(id: string): Promise<Message | null> {
        try {
            const { data, error } = await supabase
                .from('Message')
                .select('*')
                .eq('id', id)
                .maybeSingle();
            if (error) throw error;
            return data as Message;
        } catch (e) {
            console.error('Failed to find message by id from Supabase:', e);
            return null;
        }
    }

    async create(message: Omit<Message, 'id' | 'timestamp'>): Promise<Message> {
        const id = "msg_" + Date.now() + "_" + Math.random().toString(36).substr(2, 9);
        const record = { ...message, id, timestamp: new Date().toISOString() } as Message;
        try {
            const { data, error } = await supabase
                .from('Message')
                .insert(record)
                .select()
                .single();
            if (error) throw error;
            return data as Message;
        } catch (e) {
            console.warn('Failed to create message in Supabase, using local fallback:', e);
            return record;
        }
    }

    async update(message: Message): Promise<void> {
        try {
            const { error } = await supabase
                .from('Message')
                .update(message)
                .eq('id', message.id);
            if (error) throw error;
        } catch (e) {
            console.error('Failed to update message in Supabase:', e);
        }
    }

    async markAsRead(senderId: string, receiverId: string): Promise<void> {
        try {
            const { error } = await supabase
                .from('Message')
                .update({ isRead: true })
                .match({ senderId, receiverId, isRead: false });
            if (error) throw error;
        } catch (e) {
            console.error('Failed to mark messages as read in Supabase:', e);
        }
    }
}
